    reachable = [[False] * w for _ in range(h)]
    queue = deque()

    # Start with all boundary 0s
    for r in range(h):
        for c in [0, w-1]:
            if grid[r][c] == 0:
                reachable[r][c] = True
                queue.append((r, c))
    for c in range(w):
        for r in [0, h-1]:
            if grid[r][c] == 0:
                if not reachable[r][c]:
                    reachable[r][c] = True
                    queue.append((r, c))

    # BFS through all 0s
